const source = $('Set Source').first().json.source;
const criteriaItems = $('Build DOU URLs').all();
const inputItems = $input.all();
const allJobs = [];

for (let i = 0; i < inputItems.length; i++) {
  const inputItem = inputItems[i];
  const category = criteriaItems[i]?.json?.category || '';
  const raw = inputItem.json.rss?.channel?.item;
  if (!raw) continue;

  const items = Array.isArray(raw) ? raw : [raw];
  const companySuffixes = /,\s*(?:Inc\.|Ltd\.|LLC|GmbH|d\.o\.o\.|S\.A\.|s\.r\.o\.|AB|BV|PLC|Corp\.|Co\.|Group|Limited)/i;

  for (const item of items) {
    const rawTitle = (item.title || '').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&');

    let jobTitle = rawTitle;
    let company = null;
    let salary = null;
    let locations = [];
    let remote = false;

    const idx = rawTitle.indexOf(' \u0432 ');
    if (idx !== -1) {
      jobTitle = rawTitle.substring(0, idx).trim();
      let rest = rawTitle.substring(idx + 3).trim();

      const suffixMatch = rest.match(companySuffixes);
      let companyEnd;

      if (suffixMatch) {
        companyEnd = suffixMatch.index + suffixMatch[0].length;
      } else {
        companyEnd = rest.indexOf(',');
        if (companyEnd === -1) companyEnd = rest.length;
      }

      company = rest.substring(0, companyEnd).trim();
      const details = rest.substring(companyEnd).replace(/^,\s*/, '');

      if (details) {
        for (const part of details.split(',').map(s => s.trim()).filter(Boolean)) {
          if (/(?:\u0432\u0456\u0434|\u0434\u043e)\s*\$[\d\s]|^\$[\d]/.test(part)) {
            salary = part;
          } else if (/\u0432\u0456\u0434\u0434\u0430\u043b\u0435\u043d\u043e|remote/i.test(part)) {
            remote = true;
          } else if (/\u0437\u0430 \u043a\u043e\u0440\u0434\u043e\u043d\u043e\u043c/i.test(part)) {
          } else {
            locations.push(part);
          }
        }
      }
    }

    const url = (item.link || '').replace(/\?utm_source=jobsrss/, '');

    allJobs.push({
      json: {
        title: jobTitle,
        company,
        url,
        description: item.description || '',
        source,
        salary,
        location: locations.join(', ') || null,
        remote,
        publishedAt: item.pubDate || null,
        rawData: item,
        category,
      }
    });
  }
}

return allJobs;

const source = $('Set Source').first().json.source;
const jobs = $input.all().map(i => i.json);

return [{json: {body: jobs, count: jobs.length, source}}];

